import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Construct the 16-point alternating-corner triangular-lattice cluster."""
    rt3 = np.sqrt(3.0)
    corners = {(2, 0), (0, -2), (-2, 2)}
    axial = [
        (q, r)
        for q in range(-2, 3)
        for r in range(-2, 3)
        if max(abs(q), abs(r), abs(q + r)) <= 2
        and (q, r) not in corners
    ]
    points = np.asarray(
        [[q + 0.5 * r, 0.5 * rt3 * r] for q, r in axial],
        dtype=float,
    )
    return points - points.mean(axis=0, keepdims=True)

